# ───────────────────────── 12 ─────────────────────────
CHAPTERS.append({
    "title": "الرحلات: رحلات المجموعة ورحلات التكتل",
    "intro": "رحلات الطيران يديرها موظف في إدارة الحج هو مسؤول الطيران: ينشئ الرحلات، ويضع عليها المجموعات، كل مجموعة كاملة. لا يوجد في المنصة إجراء يرسل به رئيس التكتل أو رئيس المجموعة طلب حجز أو ينشئ رحلة: يتواصل رئيس التكتل مع مسؤول الطيران مباشرة، شفهياً أو بأي وسيلة، ويتفقان على موعد سفر مجموعاته، ثم يضعها مسؤول الطيران على الرحلة. حين توضع المجموعة على رحلة يسافر عليها كل المسجلين فيها وفريقها، ومن يُسجَّل فيها بعد ذلك يلحق بها تلقائياً. صفحة «الرحلات» في بوابة الإداريين للاطلاع: يرى فيها رئيس التكتل رحلات مجموعاته، ويرى رئيس المجموعة وفريقه رحلتي مجموعتهم. الأمثلة: عبد الرحمن العلي (رئيس تكتل النور) وأحمد سليمان الحمصي (رئيس المجموعة 27).",
    "sections": [
        {"title": "رئيس التكتل ومعاونه", "steps": [
            S("رحلات التكتل", "في الأعلى أربعة أرقام: عدد الحجاج والإداريين في مجموعات تكتلك، ومن منهم على رحلة ذهاب، ومن على رحلة عودة، ومن بقي بلا رحلة ذهاب. وتحتها تذكير بأن مسؤول الطيران هو من يضع المجموعات على الرحلات.", "cfl-top",
              do=["اضغط «الرحلات» في شريط التنقل."], r="تفتح صفحة رحلات تكتلك.",
              note="الصفحة للاطلاع فقط: لا إسناد فيها ولا طلبات. لتحديد موعد سفر مجموعة تواصل مع مسؤول الطيران مباشرة."),
            S("مجموعات تكتلي ورحلاتها", "لكل مجموعة: عدد أفرادها (العائلات وفريق المجموعة)، ورحلة الذهاب ورحلة العودة بالرقم والتاريخ والساعة. «لم تُسند بعد» يعني أن المجموعة لم توضع على رحلة في هذا الاتجاه. القفل بجانب رقم الرحلة يعني أنها أُقفلت وصدر كشف ركابها.", "cfl-table",
              do=["راجع المجموعات التي لم تُسند بعد، واتفق مع مسؤول الطيران على موعدها."], r="—"),
            S("بطاقات الرحلات", "لكل رحلة عليها مجموعات من تكتلك بطاقة: الاتجاه، ورقم الرحلة والناقل، والمسار، والموعد، ومكان التجمّع، وأرقام مجموعاتك عليها، وحالتها. إن أُجّلت الرحلة أو حُوّلت وجهتها يظهر ذلك في البطاقة.", "cfl-cards",
              do=["أبلغ رؤساء المجموعات بموعد التجمّع."], r="—"),
        ]},
        {"title": "رئيس المجموعة وفريقه", "steps": [
            S("رحلات المجموعة", "رئيس المجموعة ومعاونه والموجّه يرون رحلة ذهاب المجموعة ورحلة عودتها (والمنسق التقني يرى رحلات مجموعاته المفروزة له): الرقم والناقل والمسار والموعد والتجمّع والحالة.", "gfl-top",
              do=["اضغط «الرحلات» في شريط التنقل."], r="ترى رحلتي مجموعتك.",
              note="إن لم توضع مجموعتك على رحلة بعد تظهر رسالة بذلك. يضعها مسؤول الطيران بالتنسيق مع رئيس التكتل."),
            S("كشف المجموعة", "جدول بكل عائلة في المجموعة وأفرادها، ثم فريق المجموعة: رحلة الذهاب ورحلة العودة لكل فرد، وحالة إسناده (مسند، مثبت، صعد)، وحالته الإجمالية، واحتياجاته الخاصة.", "gfl-list",
              do=["اضغط «طباعة» وخذ الكشف معك إلى المطار."], r="يُطبع كشف المجموعة.",
              tip="العائلة التي يسجّلها المنسق في المجموعة بعد وضعها على الرحلة تظهر في الكشف على الرحلة نفسها دون أي إجراء."),
            S("تجمّع المطار يسجّل الصعود", "إذا كانت مجموعتك على رحلة ذهاب، فتجمّع «ساحة المزة ← المطار» في صفحة الميدان يرتبط بها تلقائياً. كل بطاقة تمسحها تُسجَّل صعوداً في ملف الطيران، فيرى مسؤول الطيران ومندوب المطار من صعد ومن تأخر.", "gfl-muster",
              do=["افتح التجمّع وامسح البطاقات كما في الفصل 7، ثم أغلقه."], r="تتغير حالة من مُسحت بطاقته إلى «صعد»."),
        ]},
    ],
})

FAQ = [
    ("من يحدد رحلة مجموعتي؟", "مسؤول الطيران في إدارة الحج. يتفق معه رئيس التكتل مباشرة، خارج المنصة، على موعد سفر مجموعاته، ثم يضع المسؤول كل مجموعة كاملة على رحلتها. ترى النتيجة في صفحة «الرحلات»."),
    ("هل أستطيع طلب رحلة أو تغييرها من المنصة؟", "لا. لا يوجد في المنصة طلب حجز ولا طلب تغيير. تواصل مع مسؤول الطيران مباشرة، وهو من يضع المجموعة على الرحلة أو ينقلها."),
    ("سجّل المنسق عائلة جديدة في مجموعتي بعد وضعها على الرحلة، هل تسافر معنا؟", "نعم. كل من يُسجَّل في المجموعة يلحق برحلتها تلقائياً، ما دامت فيها مقاعد ولم تُقفل. وإلا يعالجه مسؤول الطيران."),
    ("هل يمكنني أن أكون حاجاً وإدارياً في الموسم نفسه؟", "لا. لكل شخص نوع حساب واحد في المنصة. إذا كان لرقمك حساب حاج لا يمكن إنشاء حساب إداري به."),
    ("هل أتقدم بأكثر من صفة؟", "لا. صفة واحدة في الموسم. يمكنك الاستمرار في صفتك السابقة أو التقدم لصفة أخرى تفتحها وثائقك."),
    ("لماذا تظهر صفة مقفلة؟", "لأن ملفك يخلو مما تطلبه (وثيقة أو شهادة أو مهارة)، أو لأن عمرك أو جنسك أو خبرتك لا تناسبها بحسب جدول الإدارة. يظهر تحت البطاقة ما ينقصك وأين تضيفه."),
    ("ما الفرق بين «مطلوبة» و«تقوّي الطلب»؟", "المطلوبة لا يُقدَّم الطلب دونها. التي تقوّي الطلب تظهر في طلبك إن كانت في ملفك، ولا تمنع التقديم إن لم تكن."),
    ("متى أدفع رسم التسجيل؟", "بعد ثبوت أهليتك للصفة التي اخترتها فقط. التحقق من الأهلية يسبق الدفع، فلا تدفع رسماً عن صفة لا تستوفي شروطها."),
    ("متى أُعفى من الامتحانين؟", "عند الاستمرار في الصفة نفسها إذا بلغ تقييمك في آخر موسم الحد الذي تحدده الإدارة ولم تنقطع أكثر من موسم."),
    ("وثيقتي منتهية الصلاحية، ماذا أفعل؟", "اضغط «حدّثها الآن» وارفع نسخة صادرة هذا الموسم. مدة صلاحية كل وثيقة تحددها الإدارة."),
    ("هل امتحاني مثل امتحان الصفات الأخرى؟", "لا. لكل صفة امتحانها من بنك أسئلتها، وتشترك الصفات في أسئلة قليلة مثل الإسعافات الأولية والطوارئ والتعامل مع الحجاج. وتحدد الإدارة أي سؤال يدخل امتحان أي صفة."),
    ("هل أستطيع أداء الامتحان الكتابي من البيت؟", "لا. الامتحان جماعي في قاعة المركز الامتحاني لمحافظة قيدك، ولا يُفتح إلا بعد أن يفتح المشرف القاعة ويؤكد حضورك بهويتك."),
    ("وصلت إلى القاعة بعد بدء الامتحان", "يؤكد المشرف حضورك فتدخل، لكن بالوقت المتبقي فقط. وبعد أن ينهي المشرف الامتحان لا يدخله أحد، ومن لم يحضر يُسجَّل غائباً."),
    ("لماذا علامتي «مبدئية»؟", "لأن في امتحانك أسئلة تحريرية لم تُصحَّح بعد، فتُحسب صفراً مؤقتاً. تكتمل علامة الكتابي حين يصححها المصحح، وتراها في الصفحة نفسها."),
    ("كيف تُحسب النتيجة النهائية؟", "بالقواعد التي تضبطها إدارة الامتحانات للموسم («قواعد النجاح»)، وهي ليست ثابتة، بل تضبطها الإدارة لكل موسم: وزن الكتابي ووزن الشفهي (مجموعهما 100)، وعلامة النجاح، وحد أدنى للكتابي وحده لا يُستدعى من ينزل عنه إلى الشفهي. وفي هذه النسخة: 60% للكتابي و40% للشفهي، والنجاح من 70، وحد الكتابي 70. وتظهر القواعد نفسها في صفحة الامتحان ونتيجتك."),
    ("كيف أتقدم لرئاسة تكتل؟", "لا يُتقدَّم لها. إذا استوفيت شروط الترشح التي تعلنها الإدارة ترشّح نفسك في صفحة «التكتل» عند فتح الترشح، وينتخب رؤساء المجموعات الرؤساء."),
    ("هل أختار رقم مجموعتي وسعتها؟", "لا. الرقم يُعطى تلقائياً بالتسلسل حين ترسل الطلب، والسعة تحددها إدارة الإداريين عند اعتماد مجموعتك، بفئات بحسب خبرتك في رئاسة المجموعات وتقييمك فيها. ولا يلزم الفريق للطلب: تدعوه بعد الاعتماد."),
    ("من دعوته في مجموعة أخرى", "لا يمكن دعوة من ضمّته مجموعة أخرى؛ يظهر أمامه «في المجموعة N». اختر غيره."),
    ("متى تُفتح صفحة الميدان؟", "بعد اعتماد المجموعة من إدارة الإداريين وتوقيع ميثاق الفريق."),
    ("هل يضع المنسق التقني الحاج في مجموعة عندما يسجّل طلبه؟", "لا. التسجيل في المكتب لا يضع أحداً في مجموعة. في مرحلة التفويج يختار الحاج مجموعته، ويسجّله فيها منسق التكتل المفروز لها."),
    ("لماذا ليس في فريق مجموعتي منسق تقني؟", "لأن المنسق التقني للتكتل لا للمجموعة. لكل تكتل منسقون بعدد تحدده إدارة الإداريين، ويفرز رئيس التكتل مجموعاته عليهم: قد يكون لمنسق واحد مجموعات التكتل كلها، أو لكل منسق مجموعتان."),
    ("رفض رئيس التكتل طلب مجموعتي", "يظهر لك السبب. اطلب الانضمام إلى تكتل آخر لديه مقاعد."),
    ("عدّلت برنامج تكتلي ولا يظهر للحجاج", "التعديل ينتظر اعتماد الإدارة. يظهر للحجاج بعد الاعتماد فقط، وإن أُعيد تظهر لك أسبابه."),
]

